// "2026-09-06T…" -> "6.9.2026"; deterministic on server and client (no locale).
function formatVerifiedAt(iso?: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso ?? '');
  return m ? `${Number(m[3])}.${Number(m[2])}.${m[1]}` : '';
}

export default function ModuleHeaders({
  moduleLinks,
}: {
  moduleLinks: ModuleLinkInfo[];
}): JSX.Element {
  const { t } = useTranslation();
  const {
    markdownLayoutInfo: markdownData,
    moduleProgress,
    handleCompletionChange,
  } = useMarkdownLayout();

  const lang = useUserLangSetting();
  const setLang = useSetUserLangSetting();
  let problemIDs = [] as string[];
  // this is for modules
  try {
    const markdownProblems = useMarkdownProblems();
    if (markdownData instanceof ModuleInfo) {
      problemIDs = markdownProblems.map(problem => problem.uniqueId);
    }
  } catch (e) {
    console.log(e);
  }
  const problemsProgressInfo = useProblemsProgressInfo(problemIDs);

  // this is for solutions
  const problemSolutionContext = useContext(ProblemSolutionContext);
  const problem = problemSolutionContext?.problem;
  const verification = problemSolutionContext?.verification;
  const archiveYear = problemSolutionContext?.archiveYear;
  const suffix = useSuffix(); // a hook: called on every render, the link below is conditional

  // either prerequisites for modules or appears in for problems
  let moduleHeaderLinks: { label: string; url?: string }[];
  if (markdownData instanceof ModuleInfo) {
    moduleHeaderLinks = (markdownData.prerequisites || []).map(prereq => {
      const moduleLink = moduleLinks.find(x => x.id === prereq);
      return moduleLink
        ? {
            label: `${SECTION_LABELS[moduleLink.section]} - ${
              moduleLink.title
            }`,
            url: moduleLink.url,
          }
        : {
            label: prereq,
          };
    });
  } else {
    // this is displayed within a problem solution
    if (!problemSolutionContext) {
      throw new Error(
        'ModuleHeader is being used to render a problem; ProblemSolutionContext must be defined'
      );
    }
    const modulesThatHaveProblem =
      problemSolutionContext.modulesThatHaveProblem;
    moduleHeaderLinks = modulesThatHaveProblem.map(module => {
      return {
        label: `${SECTION_LABELS[moduleIDToSectionMap[module.id]]} - ${
          module.title
        }`,
        url: `${moduleIDToURLMap[module.id]}#problem-${problem!.uniqueId}`,
      };
    });
  }

  return (
    <>
      {markdownData instanceof ModuleInfo &&
        markdownData.frequency !== null && (
          <div className="px-0.5">
            <div className="sm:flex sm:items-center sm:justify-between mb-4 space-y-1 sm:space-y-0">
              <Frequency frequency={markdownData.frequency} />
              {problemIDs.length > 0 && (
                <DashboardProgressSmall
                  {...problemsProgressInfo}
                  total={problemIDs.length}
                />
              )}
            </div>
          </div>
        )}
      <div className="sm:flex sm:items-center sm:justify-between mb-4">
        <div className="flex-1 min-w-0">
          <h1 className="text-2xl font-bold text-gray-900 dark:text-dark-high-emphasis sm:text-3xl">
            {markdownData.title}
          </h1>
          {/* a transcribed problem's provenance is one short line (its author line said the same thing); the
              detail — which check, by which kind of reader — stays in the line's tooltip */}
          {markdownData.author && !verification && (
            <p className={`text-gray-500 dark:text-dark-med-emphasis mt-1`}>
              {t('author')}
              {markdownData.author.indexOf(',') !== -1
                ? t('author-multiple-suffix')
                : ''}
              : {markdownData.author}
            </p>
          )}
          {verification &&
            (() => {
              const date = formatVerifiedAt(verification.verifiedAt);
              const detail =
                verification.kind === 'reviewed'
                  ? t(
                      verification.verifier === 'single-pass'
                        ? 'problem-verification-single-pass'
                        : verification.verifier === 'mechanical'
                        ? 'problem-verification-reviewed-mechanical'
                        : verification.verifier === 'crop-audit'
                        ? 'problem-verification-reviewed-crop-audit'
                        : verification.verifier === 'same-model'
                        ? 'problem-verification-reviewed-same-model'
                        : 'problem-verification-reviewed',
                      { date }
                    )
                  : verification.kind === 'human'
                  ? t('problem-verification-human')
                  : t('problem-verification-legacy');
              const line =
                verification.kind === 'reviewed'
                  ? date
                    ? t('problem-provenance-checked', { date })
                    : t('problem-provenance-checked-undated')
                  : verification.kind === 'human'
                  ? t('problem-provenance-human')
                  : t('problem-provenance-unchecked');
              return (
                <p
                  className="text-gray-500 dark:text-dark-med-emphasis text-xs mt-1"
                  title={detail}
                >
                  {line}
                </p>
              );
            })()}
          {markdownData instanceof ModuleInfo && markdownData.contributors && (
            <p className={`text-gray-500 dark:text-dark-med-emphasis text-xs`}>
              {t('contributor')}
              {markdownData.contributors.indexOf(',') !== -1
                ? t('contributors-multiple-suffix')
                : ''}
              : {markdownData.contributors}
            </p>
          )}
        </div>
        {markdownData instanceof ModuleInfo && (
          <div className="hidden lg:flex-shrink-0 lg:flex ml-4">
            <MarkCompleteButton
              state={moduleProgress}
              onChange={handleCompletionChange}
            />
          </div>
        )}
        {/* {markdownData instanceof ModuleInfo &&
          `Last Updated: ${time_ago(markdownData.gitAuthorTime)}`
        } */}
      </div>

      {/*{moduleHeaderLinks?.length > 0 && (*/}
      {/*  <ModuleHeadersLinkList*/}
      {/*    title={*/}
      {/*      markdownData instanceof ModuleInfo ? 'Prerequisites' : 'Appears In'*/}
      {/*    }*/}
      {/*    links={moduleHeaderLinks}*/}
      {/*  />*/}
      {/*)}*/}

      {markdownData instanceof ModuleInfo && markdownData.description && (
        <p className="italic mb-4">{markdownData.description}</p>
      )}

      <div className="rounded-md bg-gray-50 dark:bg-gray-900 px-4 py-5 sm:p-6 mb-4">
        <div className="flex items-center justify-between">
          {/* <Menu as="div" className="inline-block text-left relative">
            {({ open }) => (
              <>
                {/* <div className="-mt-1">
                  <Menu.Button
                    className="inline-flex items-center w-full px-1 -mx-1 rounded-md text-sm font-medium text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-50 dark:focus:ring-offset-gray-900 focus:ring-blue-500"
                    style={{ width: 'fit-content' }}
                  >
                    Language: {LANGUAGE_LABELS[lang]}
                    <ChevronDownIcon
                      className="-mr-1 ml-1 h-5 w-5 text-gray-500 dark:text-gray-400"
                      aria-hidden="true"
                    />
                  </Menu.Button>
                </div>

                <Transition
                  show={open}
                  as={Fragment}
                  enter="transition ease-out duration-100"
                  enterFrom="transform opacity-0 scale-95"
                  enterTo="transform opacity-100 scale-100"
                  leave="transition ease-in duration-75"
                  leaveFrom="transform opacity-100 scale-100"
                  leaveTo="transform opacity-0 scale-95"
                >
                  <Menu.Items
                    static
                    className="origin-top-left absolute z-10 left-0 mt-2 w-56 rounded-md shadow-lg bg-white dark:bg-gray-800 ring-1 ring-black ring-opacity-5 focus:outline-none"
                  >
                    <div className="py-1">
                      {(['cpp', 'java', 'py'] as const).map(lang => (
                        <Menu.Item key={lang}>
                          {({ active }) => (
                            <button
                              className={classNames(
                                active
                                  ? 'bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-gray-100'
                                  : 'text-gray-700 dark:text-gray-300',
                                'block px-4 py-2 text-sm focus:outline-none w-full text-left'
                              )}
                              onClick={() => setLang(lang)}
                            >
                              {LANGUAGE_LABELS[lang]}
                            </button>
                          )}
                        </Menu.Item>
                      ))}
                    </div>
                  </Menu.Items>
                </Transition>
              </>
            )}
          </Menu> */}

          {/* a transcribed problem page is generated from its paper JSON (scripts/problems-to-site.mjs): an edit
              made to the page would be overwritten on the next publication, so it gets no editor link. Other pages
              open in GitHub's editor, which forks the repository and opens a pull request; the /editor page still
              commits through the USACO Guide's GitHub App to a fork of its repository. */}
          {!verification && (
            <a
              href={encodeURI(
                `https://github.com/OlympiadsXYZ/olympiads-xyz/edit/master/${suffix}`
              )}
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm font-medium text-gray-600 hover:text-gray-900 my-0 dark:text-gray-400 dark:hover:text-gray-100 group inline-flex items-center space-x-1.5"
            >
              <span>{t('edit_this_page')}</span>
              <ExternalLinkIcon className="h-5 w-5 text-gray-400 group-hover:text-gray-600 dark:text-gray-500 dark:group-hover:text-gray-300" />
            </a>
          )}
        </div>

        {moduleHeaderLinks?.length > 0 && (
          <div>
            <div className="h-4 sm:h-6" />
            <h3 className="text-sm leading-5 font-medium text-gray-800 my-0 dark:text-gray-200">
              {markdownData instanceof ModuleInfo
                ? t('prerequisites')
                : t('appears_in')}
            </h3>
            <div className="text-sm leading-5 text-gray-700 mt-1 no-y-margin dark:text-gray-300">
              <ul className="list-disc list-inside pl-3 space-y-1">
                {moduleHeaderLinks.map(link => (
                  <li key={link.url ?? link.label}>
                    {link.url ? (
                      <a
                        href={link.url}
                        target="_blank"
                        rel="noreferrer"
                        className="underline text-black dark:text-gray-200"
                      >
                        {link.label}
                      </a>
                    ) : (
                      <span className="text-black dark:text-gray-200">
                        {link.label}
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {problem && (
          <div>
            <div className="h-4 sm:h-6" />
            {/* Problem-page actions for quality testers: the original PDF,
                the side-by-side compare panel and a prefilled issue. */}
            <div className="flex flex-wrap items-center gap-x-6 gap-y-2">
              <a
                href={problem.url}
                target="_blank"
                rel="noreferrer"
                className="text-sm font-medium text-gray-800 hover:text-gray-900 my-0 dark:text-gray-200 dark:hover:text-gray-100 group inline-flex items-center space-x-1.5"
              >
                <span>{t(viewStatementKey(problem.url))}</span>
                <ExternalLinkIcon className="h-5 w-5 text-gray-400 group-hover:text-gray-600 dark:text-gray-400 dark:group-hover:text-gray-300" />
              </a>
              <CompareToggleButton />
              <ReportIssueLink />
            </div>
            {/* the paper's page in the archive: its solutions, results and
                the other papers of that year */}
            {archiveYear && (
              <Link
                to={archiveYear.path}
                className="mt-3 inline-block text-sm font-medium text-blue-700 hover:text-blue-800 hover:underline dark:text-blue-400 dark:hover:text-blue-300"
              >
                {t('archive_year_link', { paper: archiveYear.label })}{' '}
                <span aria-hidden="true">→</span>
              </Link>
            )}
          </div>
        )}
      </div>
    </>
  );
}
